function getByPath(obj, path) {
  try {
    return path.split('.').reduce((o, k) => (o == null ? undefined : o[k]), obj);
  } catch (e) {
    return undefined;
  }
}

function firstNonEmpty(obj, paths) {
  for (const p of paths) {
    const v = getByPath(obj, p);
    if (v !== undefined && v !== null && String(v).trim() !== '') {
      return typeof v === 'string' ? v : String(v);
    }
  }
  return '';
}

function decodeBase64Url(data) {
  if (!data) return '';
  try {
    const normalized = String(data).replace(/-/g, '+').replace(/_/g, '/');
    return Buffer.from(normalized, 'base64').toString('utf-8');
  } catch (e) {
    return '';
  }
}

function findMimePart(payload, mimeType) {
  let result = '';
  if (!payload) return result;
  if (payload.mimeType === mimeType && payload.body && payload.body.data) {
    result += decodeBase64Url(payload.body.data);
  }
  if (Array.isArray(payload.parts)) {
    for (const part of payload.parts) {
      result += findMimePart(part, mimeType);
    }
  }
  return result;
}

function getHeaderFromArray(headers, name) {
  if (!Array.isArray(headers)) return '';
  const target = name.toLowerCase();
  const match = headers.find(h => h && typeof h.name === 'string' && h.name.toLowerCase() === target);
  return match ? (match.value || '') : '';
}

function getHeaderFromObject(headersObj, name) {
  if (!headersObj || typeof headersObj !== 'object') return '';
  const key = Object.keys(headersObj).find(k => k.toLowerCase() === name.toLowerCase());
  return key ? (headersObj[key] || '') : '';
}

const results = [];

for (const item of $input.all()) {
  const message = item.json || {};
  const payload = message.payload || {};

  const headerArray = payload.headers || message.headers || [];
  const headerObject = (!Array.isArray(headerArray) && typeof headerArray === 'object') ? headerArray : null;

  function getHeader(name) {
    let v = '';
    if (Array.isArray(headerArray)) v = getHeaderFromArray(headerArray, name);
    if (!v && headerObject) v = getHeaderFromObject(headerObject, name);
    return v;
  }

  const subject = firstNonEmpty(message, ['Subject', 'subject']) || getHeader('Subject');
  const from = firstNonEmpty(message, ['From', 'from', 'sender', 'Sender']) || getHeader('From');
  const to = firstNonEmpty(message, ['To', 'to']) || getHeader('To');

  let date = firstNonEmpty(message, ['Date', 'date']) || getHeader('Date');
  if (!date && message.internalDate) {
    const ms = Number(message.internalDate);
    if (!isNaN(ms)) date = new Date(ms).toUTCString();
  }

  const snippet = firstNonEmpty(message, ['snippet', 'Snippet']);

  let bodyText = firstNonEmpty(message, ['textPlain', 'text', 'bodyText', 'body.plain', 'body.text']);
  let bodyHtml = firstNonEmpty(message, ['textHtml', 'html', 'bodyHtml', 'body.html']);

  if (!bodyText) bodyText = findMimePart(payload, 'text/plain');
  if (!bodyHtml) bodyHtml = findMimePart(payload, 'text/html');

  if (!bodyText && !bodyHtml && payload.body && payload.body.data) {
    const decoded = decodeBase64Url(payload.body.data);
    if (payload.mimeType === 'text/html') {
      bodyHtml = decoded;
    } else {
      bodyText = decoded;
    }
  }

  if (!bodyText && !bodyHtml && message.raw) {
    const rawDecoded = decodeBase64Url(message.raw);
    const splitParts = rawDecoded.split(/\r?\n\r?\n/);
    bodyText = splitParts.slice(1).join('\n\n') || rawDecoded;
  }

  results.push({
    json: {
      messageId: message.id || message.messageId || '',
      threadId: message.threadId || '',
      subject: subject || '',
      from: from || '',
      to: to || '',
      date: date || '',
      snippet: snippet || '',
      bodyText: bodyText || '',
      bodyHtml: bodyHtml || ''
    }
  });
}

return results;

// IANA timezone used to format "Date Applied". Gmail header dates and the fallback
// "today" value are both converted into this timezone before formatting, so the date
// written to the sheet matches your local calendar day instead of UTC (n8n/Gmail
// timestamps are UTC internally, which can roll a late-evening email into "tomorrow"
// if you just take the UTC date). Change this if you're not in Toronto.
const APP_TIMEZONE = 'America/Toronto';

function toLocalDateString(date, timeZone) {
  try {
    const fmt = new Intl.DateTimeFormat('en-CA', {
      timeZone: timeZone,
      year: 'numeric',
      month: '2-digit',
      day: '2-digit'
    });
    return fmt.format(date); // en-CA locale formats as YYYY-MM-DD
  } catch (e) {
    return date.toISOString().split('T')[0];
  }
}

const CONFIRMATION_PHRASES = [
  /thank you for applying/i,
  /thanks for applying/i,
  /thank you for taking the time to apply/i,
  /we.?ve received your application/i,
  /we have received your application/i,
  /application received/i,
  /your application has been submitted/i,
  /application submitted successfully/i,
  /thanks for your interest/i,
  /thank you for your interest/i,
  /candidate portal/i,
  /application confirmation/i,
  /successfully applied/i,
  /you.?ve applied/i,
  /your application to/i,
  /your application was sent/i,
  /we appreciate your interest/i,
  /application was sent/i,
  /application has been received/i,
  /reviewing your candidate profile/i,
  /currently reviewing your (?:application|candidate profile)/i
];

// Job alert / recommendation digests (Glassdoor "Job alert: X", Indeed "N new ... jobs",
// "X and N more jobs in <City> for you") share enough vocabulary ("apply", "Indeed", etc.)
// with real confirmations that the fallback classifier below can mistake them for one.
// Any of these patterns matching forces isJobApplication back to false, regardless of
// what else matched.
const JOB_ALERT_PATTERNS = [
  /\bjob alerts?\b/i,
  /\d+\s+more jobs?\b/i,
  /\byour job listings? for\b/i,
  /\bsee more jobs\b/i,
  /\bnew .{0,60}opportunit(?:y|ies) in\b/i,
  /\bcreate job alerts? for related roles\b/i
];

const KNOWN_SOURCES = [
  { name: 'LinkedIn', pattern: /linkedin\.com|linkedin/i },
  { name: 'Indeed', pattern: /indeed\.com|indeed/i },
  { name: 'Greenhouse', pattern: /greenhouse\.io|greenhouse/i },
  { name: 'Lever', pattern: /lever\.co|lever/i },
  { name: 'Workday', pattern: /myworkday\.com|workday/i },
  { name: 'Ashby', pattern: /ashbyhq\.com|ashby/i },
  { name: 'SmartRecruiters', pattern: /smartrecruiters\.com|smartrecruiters/i },
  { name: 'BambooHR', pattern: /bamboohr\.com|bamboohr/i },
  { name: 'Jobvite', pattern: /jobvite\.com|jobvite/i },
  { name: 'iCIMS', pattern: /icims\.com|icims/i }
];

// Sender/domain keywords that should never be mistaken for a company name when we fall
// back to the "From" header (ATS platforms + LinkedIn/Indeed all send from their own domains).
const NON_COMPANY_SENDER_KEYWORDS = /linkedin|indeed|greenhouse|lever|workday|ashby|smartrecruiters|bamboohr|jobvite|icims|no-?reply|noreply|talent(?:acquisition)?@|careers@|jobs@/i;

const JOB_TYPE_RULES = [
  { category: 'Internship', patterns: [/\bintern(ship)?\b/i] },
  { category: 'QA', patterns: [/\bqa\b/i, /quality assurance/i, /\btest(er|ing)?\b/i, /\bsdet\b/i] },
  { category: 'Data Analyst', patterns: [/data analyst/i, /data scien/i, /business intelligence/i, /\bbi analyst\b/i, /\banalytics\b/i] },
  { category: 'IT Support', patterns: [/it support/i, /help ?desk/i, /technical support/i, /desktop support/i, /systems? administrator/i, /support technician/i] },
  { category: 'Web Developer', patterns: [/web develop/i, /front.?end/i, /back.?end/i, /full.?stack/i, /ui developer/i, /website develop/i] },
  { category: 'Software Developer', patterns: [/software (developer|engineer)/i, /\bsde\b/i, /programmer/i, /application developer/i, /backend engineer/i, /\bai developer\b/i, /developer/i, /engineer/i] }
];

function categorizeJobType(jobTitle, fallbackText) {
  const titleText = (jobTitle || '').toLowerCase();
  const wideText = ((jobTitle || '') + ' ' + (fallbackText || '')).toLowerCase();

  for (const rule of JOB_TYPE_RULES) {
    if (rule.patterns.some(p => p.test(titleText))) return rule.category;
  }
  for (const rule of JOB_TYPE_RULES) {
    if (rule.patterns.some(p => p.test(wideText))) return rule.category;
  }
  return 'Other';
}

function stripHtml(html) {
  if (!html) return '';
  return html
    .replace(/<style[^>]*>[\s\S]*?<\/style>/gi, ' ')
    .replace(/<script[^>]*>[\s\S]*?<\/script>/gi, ' ')
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<\/p>/gi, '\n')
    .replace(/<\/tr>/gi, '\n')
    .replace(/<\/div>/gi, '\n')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&#39;/g, "'")
    .replace(/&quot;/g, '"')
    .replace(/[ \t]+/g, ' ')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

function tryMatch(text, patterns) {
  for (const p of patterns) {
    const m = text.match(p);
    if (m && m[1]) return m[1].trim();
  }
  return '';
}

// Handles cases where job title AND company appear together in one sentence, in either
// order ("applying for X at Y" / "application sent to Y for X"). Tried before the
// single-field fallbacks further down since it's far more reliable when it matches.
// TITLE_CHARS allows parentheses so titles like "AI Developer (Fixed term contract)"
// are captured whole instead of getting cut off at the "(".
function extractTitleCompanyPair(text) {
  if (!text) return null;
  const TITLE_CHARS = "[\\w&.,\\/\\-\\+\\(\\) ]";
  const rules = [
    { re: new RegExp("\\b(?:applying for|applied for|application for|apply for|application to)\\s+(?:the\\s+)?(" + TITLE_CHARS + "{1,90}?)\\s+(?:role|position|job)?\\s*(?:at|with|@)\\s+([A-Z][\\w&.,'\\-\\& ]{1,60}?)(?:[.,;:\\n!]|$)", "i"), titleGroup: 1, companyGroup: 2 },
    { re: new RegExp("\\b(?:for the position of|for the role of)\\s+(" + TITLE_CHARS + "{1,90}?)\\s+(?:at|with|@)\\s+([A-Z][\\w&.,'\\-\\& ]{1,60}?)(?:[.,;:\\n!]|$)", "i"), titleGroup: 1, companyGroup: 2 },
    { re: new RegExp("application (?:was )?sent to\\s+([A-Z][\\w&.,'\\-\\& ]{1,60}?)\\s+for\\s+(?:the\\s+)?(" + TITLE_CHARS + "{1,90}?)(?:[.,;:\\n!]|$)", "i"), titleGroup: 2, companyGroup: 1 },
    { re: new RegExp("you (?:have )?applied for\\s+(" + TITLE_CHARS + "{1,90}?)\\s+at\\s+([A-Z][\\w&.,'\\-\\& ]{1,60}?)(?:[.,;:\\n!]|$)", "i"), titleGroup: 1, companyGroup: 2 },
    // LinkedIn Easy Apply block layout: "Your application was sent to <Company>" sits on
    // its own line, and the job title is the very next line (no "at Company" sentence at
    // all) - e.g. "Your application was sent to Helic & Co\n\nJunior Software Developer\nHelic & Co\n..."
    { re: new RegExp("application (?:was )?sent to\\s+([A-Z][\\w&.,'\\-\\& ]{1,60})\\s*\\n+\\s*(" + TITLE_CHARS + "{1,90})\\s*\\n", "i"), titleGroup: 2, companyGroup: 1 }
  ];
  for (const rule of rules) {
    const m = text.match(rule.re);
    if (m && m[rule.titleGroup] && m[rule.companyGroup]) {
      return {
        jobTitle: m[rule.titleGroup].trim().replace(/[.,]$/, ''),
        company: m[rule.companyGroup].trim().replace(/[.,]$/, '')
      };
    }
  }
  return null;
}

// Many ATS confirmation emails never state "at <Company>" anywhere - the only place the
// company appears is the email signature, e.g. "Purolator Talent Acquisition Team" or
// "The Acme Recruiting Team". Used only as a fallback once sentence-level extraction fails.
function extractCompanyFromSignature(text) {
  if (!text) return '';
  const patterns = [
    /\b([A-Z][\w&.,'\- ]{1,60}?)\s+(?:Talent Acquisition|Recruiting|Recruitment|HR|Careers|Hiring)\s+Team\b/,
    /(?:Best regards|Sincerely|Regards|Warm regards|Kind regards|Thank you),?\s+(?:The\s+)?([A-Z][\w&.,'\- ]{1,60}?)\s+(?:Team|Talent Acquisition Team|Recruiting Team|HR Team|Careers Team)\b/i,
    /(?:^|\n)\s*(?:The\s+)?([A-Z][\w&.,'\- ]{2,60}?)\s+Team\s*(?:\n|$)/m
  ];
  return tryMatch(text, patterns);
}

// LinkedIn ("Easy Apply") confirmation emails rarely put job title and company in one
// sentence - they're often split across a subject line and a separate body line. These
// patterns are tried specifically when the source is LinkedIn (or as a general fallback)
// once nothing else has matched.
function extractLinkedInFields(subject, body) {
  const company = tryMatch(subject, [
    /application was sent to\s+([A-Z][\w&.,'\-\& ]{1,60})/i,
    /your application to\s+([A-Z][\w&.,'\-\& ]{1,60})/i
  ]) || tryMatch(body, [
    /application was sent to\s+([A-Z][\w&.,'\-\& ]{1,60})/i,
    /applied to\s+([A-Z][\w&.,'\-\& ]{1,60})/i
  ]);

  const jobTitle = tryMatch(subject, [
    /for the\s+([A-Za-z0-9][\w&.,\/\-\+\(\) ]{1,90}?)\s+(?:role|position)/i
  ]) || tryMatch(body, [
    /you applied for\s+([A-Za-z0-9][\w&.,\/\-\+\(\) ]{1,90}?)(?:\s+at\b|[.,\n]|$)/i,
    /application for\s+(?:the\s+)?([A-Za-z0-9][\w&.,\/\-\+\(\) ]{1,90}?)(?:\s+(?:role|position))?\s*(?:has been|was)/i
  ]);

  return { company: company || '', jobTitle: jobTitle || '' };
}

// Indeed confirmation emails ("Indeed Application: <Title>") put the job title in the
// subject line reliably, and the company name appears in a "The following items were
// sent to <Company>. Good luck!" sentence in the body - not in an "at <Company>" sentence,
// so the generic combined extractor above never catches it.
function extractIndeedFields(subject, body) {
  let jobTitle = tryMatch(subject, [
    /^indeed application:\s*(.+)$/i
  ]);
  if (!jobTitle) {
    jobTitle = tryMatch(body, [
      /application submitted\s*\n+\s*([A-Za-z0-9][\w&.,\/\-\+\(\) ]{1,90})/i
    ]);
  }

  const company = tryMatch(body, [
    /(?:were sent to|was sent to|items were sent to)\s+([A-Z][\w&.,'\-\& ]{1,60}?)\.\s*Good luck/i,
    /application (?:was |has been )?submitted to\s+([A-Z][\w&.,'\-\& ]{1,60})/i
  ]);

  return { jobTitle: jobTitle || '', company: company || '' };
}

// Workday-hosted career sites (used by many large companies, e.g. Roche) rarely put the
// company name in a sentence at all - the confirmation body just says "Thank you for
// applying to the <Title> position" and signs off with a department name like "People and
// Culture" rather than the company. The one reliable place the company shows up is the
// Workday application URL itself, e.g. https://roche.wd3.myworkdayjobs.com/... or a
// careers.<company>.com link in the footer.
function extractWorkdayFields(text) {
  let company = '';
  const wdMatch = text.match(/https?:\/\/([a-z0-9][a-z0-9\-]*)\.wd\d+\.myworkday(?:jobs)?\.com/i);
  if (wdMatch && wdMatch[1]) {
    company = wdMatch[1];
  }
  if (!company) {
    const careersMatch = text.match(/careers\.([a-z0-9\-]+)\.(?:com|io|co|net|org)/i);
    if (careersMatch && careersMatch[1]) company = careersMatch[1];
  }
  if (company) {
    company = company
      .split(/[-_]/)
      .filter(Boolean)
      .map(w => w.charAt(0).toUpperCase() + w.slice(1))
      .join(' ');
  }
  return { company: company || '' };
}

const results = [];

for (const item of $input.all()) {
  const d = item.json;
  const subject = d.subject || '';
  const from = d.from || '';
  const bodyTextRaw = d.bodyText || '';
  const bodyHtmlText = stripHtml(d.bodyHtml || '');
  const combinedBody = (bodyTextRaw + '\n' + bodyHtmlText).trim();
  const searchable = subject + '\n' + from + '\n' + combinedBody;

  // Check the sender address and subject first (authoritative, low false-positive risk).
  // Only fall back to scanning the full body if neither matches - some ATS confirmation
  // emails (e.g. Roche's Workday email) link to the company's LinkedIn/Instagram/Facebook
  // pages in the footer, which would otherwise cause a false "LinkedIn" source match.
  let source = '';
  for (const s of KNOWN_SOURCES) {
    if (s.pattern.test(from) || s.pattern.test(subject)) { source = s.name; break; }
  }
  if (!source) {
    for (const s of KNOWN_SOURCES) {
      if (s.pattern.test(combinedBody)) { source = s.name; break; }
    }
  }

  const isConfirmation = CONFIRMATION_PHRASES.some(p => p.test(searchable));
  const isJobAlertDigest = JOB_ALERT_PATTERNS.some(p => p.test(subject) || p.test(combinedBody));
  const isJobApplication = !isJobAlertDigest && (isConfirmation || (!!source && /appli/i.test(searchable)));

  // Priority 1: combined "title at company" pattern (checked in subject, then body)
  const pair = extractTitleCompanyPair(subject) || extractTitleCompanyPair(combinedBody);

  let company = pair ? pair.company : '';
  let jobTitle = pair ? pair.jobTitle : '';

  // Priority 2: LinkedIn-specific phrasing (only helps when source is LinkedIn, but cheap
  // to try regardless since the patterns are fairly specific)
  if (!company || !jobTitle) {
    const li = extractLinkedInFields(subject, combinedBody);
    if (!company && li.company) company = li.company;
    if (!jobTitle && li.jobTitle) jobTitle = li.jobTitle;
  }

  // Priority 2b: Indeed-specific phrasing (subject "Indeed Application: <Title>" plus the
  // "sent to <Company>. Good luck!" body sentence)
  if (!company || !jobTitle) {
    const idx = extractIndeedFields(subject, combinedBody);
    if (!company && idx.company) company = idx.company;
    if (!jobTitle && idx.jobTitle) jobTitle = idx.jobTitle;
  }

  // Priority 2c: Workday-specific fallback (company pulled from the application URL)
  if (!company) {
    const wd = extractWorkdayFields(searchable);
    if (wd.company) company = wd.company;
  }

  // Priority 3: individual fallback patterns for company
  if (!company) {
    company = tryMatch(subject, [
      /your application to\s+([A-Z][\w&.,'\- ]{1,60})/i,
      /application to\s+([A-Z][\w&.,'\- ]{1,60})/i,
      /applying to\s+([A-Z][\w&.,'\- ]{1,60})/i,
      /at\s+([A-Z][\w&.,'\- ]{1,60})$/i
    ]);
  }
  if (!company) {
    company = tryMatch(combinedBody, [
      /your application (?:to|for|at)\s+([A-Z][\w&.,'\- ]{1,60})/i,
      /applied to\s+([A-Z][\w&.,'\- ]{1,60})/i,
      /application (?:to|with)\s+([A-Z][\w&.,'\- ]{1,60})/i,
      /thank you for your interest in\s+([A-Z][\w&.,'\- ]{1,60})/i,
      /company:\s*([A-Z][\w&.,'\- ]{1,60})/i,
      /\bat\s+([A-Z][\w&.,'\- ]{1,60}?)(?:[.,;:\n!]|$)/
    ]);
  }
  // Priority 4: signature line ("<Company> Talent Acquisition Team", etc.) - catches
  // emails like the Purolator example where the company only appears in the sign-off.
  if (!company) {
    company = extractCompanyFromSignature(combinedBody);
  }
  // Priority 5: "From" header display name, excluding known ATS/job-board senders.
  if (!company && from) {
    const fromMatch = from.match(/"?([^"<]+)"?\s*<.*>/);
    if (fromMatch && fromMatch[1] && !NON_COMPANY_SENDER_KEYWORDS.test(fromMatch[1]) && !NON_COMPANY_SENDER_KEYWORDS.test(from)) {
      company = fromMatch[1].trim();
    }
  }
  company = company.replace(/[.,]$/, '').trim();

  // Priority 3: individual fallback patterns for job title
  if (!jobTitle) {
    jobTitle = tryMatch(subject, [
      /application for\s+(?:the\s+)?([A-Za-z0-9][\w&.,\/\-\+\(\) ]{1,90}?)(?:\s+(?:role|position|job))?\s*(?:at|@|\-|$)/i,
      /applied for\s+(?:the\s+)?([A-Za-z0-9][\w&.,\/\-\+\(\) ]{1,90}?)(?:\s+(?:role|position|job))?\s*(?:at|@|\-|$)/i,
      /for the\s+([A-Za-z0-9][\w&.,\/\-\+\(\) ]{1,90}?)\s+(?:role|position)/i
    ]);
  }
  if (!jobTitle) {
    jobTitle = tryMatch(combinedBody, [
      // "apply for the X position" / "applying for the X position" - handles titles with
      // parenthetical qualifiers like "AI Developer (Fixed term contract) position"
      /\bapply(?:ing)? (?:for|to)\s+(?:the\s+)?([A-Za-z0-9][\w&.,\/\-\+\(\) ]{1,90}?)\s+position\b/i,
      /applying for\s+(?:the\s+)?([A-Za-z0-9][\w&.,\/\-\+\(\) ]{1,90}?)(?:\s+(?:role|position|job))?\s*(?:at|@|\n|\.|,)/i,
      /application for\s+(?:the\s+)?([A-Za-z0-9][\w&.,\/\-\+\(\) ]{1,90}?)(?:\s+(?:role|position|job))?\s*(?:at|@|\n|\.|,)/i,
      /position:\s*([A-Za-z0-9][\w&.,\/\-\+\(\) ]{1,90})/i,
      /job title:\s*([A-Za-z0-9][\w&.,\/\-\+\(\) ]{1,90})/i,
      /role:\s*([A-Za-z0-9][\w&.,\/\-\+\(\) ]{1,90})/i
    ]);
  }
  jobTitle = jobTitle.replace(/[.,]$/, '').trim();

  // --- Date Applied: always formatted in APP_TIMEZONE, not UTC, to avoid a late-evening
  // email rolling over to the next calendar day. ---
  let dateApplied = '';
  const dateHeader = d.date || '';
  if (dateHeader) {
    const parsed = new Date(dateHeader);
    if (!isNaN(parsed.getTime())) {
      dateApplied = toLocalDateString(parsed, APP_TIMEZONE);
    }
  }
  if (!dateApplied) {
    const dm = combinedBody.match(/applied on\s+([A-Za-z]+\s+\d{1,2},?\s+\d{4})/i);
    if (dm) {
      const parsed = new Date(dm[1]);
      if (!isNaN(parsed.getTime())) dateApplied = toLocalDateString(parsed, APP_TIMEZONE);
    }
  }
  if (!dateApplied) {
    dateApplied = toLocalDateString(new Date(), APP_TIMEZONE);
  }

  const jobLocation = tryMatch(combinedBody, [
    /location:\s*([A-Za-z0-9][\w,.\-\/ ]{1,60})/i,
    /based in\s*([A-Za-z0-9][\w,.\-\/ ]{1,60})/i,
    /job location:\s*([A-Za-z0-9][\w,.\-\/ ]{1,60})/i,
    /work location:\s*([A-Za-z0-9][\w,.\-\/ ]{1,60})/i,
    /office location:\s*([A-Za-z0-9][\w,.\-\/ ]{1,60})/i
  ]) || (/\bremote\b/i.test(combinedBody) ? 'Remote' : '');

  const employmentType = tryMatch(combinedBody, [
    /employment type:\s*([A-Za-z\-\/ ]{1,30})/i,
    /job type:\s*([A-Za-z\-\/ ]{1,30})/i,
    /\b(full-time|part-time|fixed-term|fixed term contract|contract|contractor|internship|temporary|freelance|permanent|co-op)\b/i
  ]);

  // Category used to populate the Google Sheet's "Job Type" dropdown column.
  // Always resolves to one of: Software Developer, Data Analyst, IT Support,
  // Internship, QA, Web Developer, Other.
  const jobTypeCategory = categorizeJobType(jobTitle, combinedBody + ' ' + employmentType);

  const recruiterEmail = tryMatch(searchable, [
    /recruiter[^:]*:\s*[\w\s]*<?([\w.\-]+@[\w.\-]+\.\w+)>?/i
  ]);

  const recruiterName = tryMatch(combinedBody, [
    /recruiter:\s*([A-Za-z][\w'\- ]{1,50})/i,
    /your recruiter,?\s*([A-Za-z][\w'\- ]{1,50})/i,
    /hiring manager:\s*([A-Za-z][\w'\- ]{1,50})/i
  ]);

  let jobUrl = '';
  const rawHtmlOrBody = d.bodyHtml || combinedBody;
  const urlMatch = rawHtmlOrBody.match(/https?:\/\/[^\s"'<>]+(?:job|posting|career|apply|position)[^\s"'<>]*/i)
    || rawHtmlOrBody.match(/https?:\/\/[^\s"'<>]+/);
  if (urlMatch) jobUrl = urlMatch[0];

  const applicationId = tryMatch(searchable, [
    /application\s*(?:id|number|ref(?:erence)?)\s*[:#]?\s*([A-Za-z0-9\-]{3,40})/i,
    /reference\s*(?:id|number)?\s*[:#]?\s*([A-Za-z0-9\-]{3,40})/i,
    /candidate\s*id\s*[:#]?\s*([A-Za-z0-9\-]{3,40})/i
  ]);

  results.push({
    json: {
      isJobApplication,
      company: company || '',
      jobTitle: jobTitle || '',
      dateApplied: dateApplied || '',
      source: source || '',
      jobLocation: jobLocation || '',
      employmentType: employmentType || '',
      jobTypeCategory: jobTypeCategory || 'Other',
      recruiterName: recruiterName || '',
      recruiterEmail: recruiterEmail || '',
      jobUrl: jobUrl || '',
      applicationId: applicationId || '',
      emailSubject: subject || '',
      emailBody: combinedBody.substring(0, 2000)
    }
  });
}

return results;

const newRow = $('Map Fields to Sheet Row').first().json;
const existingRows = $input.all().map(i => i.json);

// Strips punctuation and common corporate suffixes (Inc, LLC, Corp, etc.) so
// "Purolator Inc" and "Purolator" (e.g. from an Indeed email vs. a direct company email
// for the same job) are recognized as the same company instead of creating a duplicate row.
const normalizeCompany = (s) => {
  let v = (s || '').toString().trim().toLowerCase();
  v = v.replace(/[.,]/g, '');
  v = v.replace(/\s+(inc|incorporated|llc|ltd|corp|corporation|company|co|limited|plc|group)$/i, '');
  return v.trim();
};

const normalizeTitle = (s) => (s || '').toString().trim().toLowerCase().replace(/\s+/g, ' ');

const isDuplicate = existingRows.some(row => {
  const rowCompany = normalizeCompany(row['Company']);
  const rowTitle = normalizeTitle(row['Job Title']);
  return rowCompany !== '' && rowCompany === normalizeCompany(newRow['Company']) && rowTitle === normalizeTitle(newRow['Job Title']);
});

return [{
  json: {
    ...newRow,
    isDuplicate
  }
}];
